from pathlib import Path
import json
from publish_trend5_20261027 import p,h,a,ul,table
PLAN=json.loads((Path(__file__).resolve().parents[1]/'docs/related-next10-2026-11-02/plan.json').read_text(encoding='utf8'))['plan']
CLAIM='https://www.samsungfire.com/v2/html/customer/13/G_030_010_010.html?init=direct'
POLICY='https://www.samsungfire.com/publication/pdf/ZPB369040_0_20260101_file1.pdf?_v=202601100034'
DND='https://pc.dnd.or.kr/DOIx.php?id=10.12779/dnd.2022.21.1.42'
PRICE='https://www.brmh.org/medi_info/non_medifee.do?site=001&user_code=009015000&CSUBCD_NM1=%ED%96%89%EC%9C%84%EB%A3%8C&CSUBCD_NM2=%EC%A0%84%EC%B2%B4&searchword=%EC%A0%84%EB%A6%BD%EC%84%A0'
DATA=[]
def add(n,desc,body,extra=None):
 d=PLAN[n-1];sources=[(d['medical'],d['label'],'검사의 역할 또는 해당 제도의 공식 설명. 개별 실손 지급 보장은 아님')]
 if n not in [4,9,10]:sources.append((CLAIM,'삼성화재 실손 청구서류 안내','구비서류의 회사별 예시. 가입 회사 요구항목은 별도 대조'))
 if extra:sources+=extra
 sources=list({x[0]:x for x in sources}.values())
 DATA.append(dict(path=d['path'],slug=d['path'].split('/')[-1],keyword=d['keyword'],title=d['title'],desc=desc,cat=d['cat'],parents=d['parents'],intent=d['intent'],sources=sources,body=body))

add(1,'청성뇌간반응검사 실비는 ABR의 시행 목적과 실제 비용 항목을 확인합니다. 순음청력검사·신생아 선별검사·장애평가를 구분하고 검사비와 진정 비용의 청구자료를 정리합니다.',[
h('청성뇌간반응검사 실비는 ABR을 받은 이유부터 확인합니다')+p('청성뇌간반응검사 실비를 준비할 때는 난청 의심으로 진료 중 시행했는지, 선별검사나 장애평가를 위해 시행했는지부터 확인하세요. 같은 검사 이름이 영수증에 있어도 진료 목적과 가입 계약이 같다는 뜻은 아닙니다. 이 글은 ABR 검사자료를 정리하는 안내이며 청각장애 등급이나 인공와우 수술 대상 여부를 판정하지 않습니다.')+p(a(PLAN[0]['medical'],'분당서울대학교병원 안내')+'는 청성뇌간반응 검사를 객관적 청력검사의 한 종류로 설명합니다. 소리에 반응해 버튼을 누르는 검사와 어떤 점이 다른지 이해하면 결과지를 잘못 제출하는 일을 줄일 수 있습니다.'),
h('ABR·순음검사·청각선별검사 자료 비교')+table(['자료에 적힌 검사','확인할 내용','혼동하지 않을 점'],[['ABR 등 정밀 청력검사','정확한 시행명·검사일·의뢰 사유','다른 청력검사 결과지를 같은 자료로 쓰지 않기'],['순음청력검사','청력도와 검사일','ABR 파형·결과 자료와 구분'],['신생아 청각선별검사','선별 시행명과 재검 안내','선별 결과와 확진을 동일하게 보지 않기'],['장애평가 자료','발급 목적과 평가 서류 비용','진료 목적 검사비와 제증명 비용 분리']])+p('AABR 등 비슷한 약어만 보고 같은 검사·같은 비용이라고 정리하지 마세요. 병원에 이번 검사명과 목적, 진료비 항목을 물어보는 것이 먼저입니다.'),
h('진정 비용이 있다면 검사비와 나눠 봅니다')+p('진정이나 별도 관찰이 있었는지는 실제 진료기록으로 확인합니다. 잠든 상태에서 검사했다는 설명만으로 수면마취 비용이 청구됐거나 입원에 해당한다고 보지 않습니다. 검사 전 금식·복용약·보호자 동행은 검사실의 개인별 안내를 따르세요.')+ul(['검사료와 약제·진정·관찰료가 각각 기재됐는지 확인','예약일과 실제 검사 시행일 구분','입원이 있었다면 실제 입퇴원 기록 별도 확인','미성년자 청구는 보험사의 법정대리인 절차 확인']),
h('청성뇌간반응검사 청구서류 준비')+p('실손용 비용 자료는 진료비 계산서·영수증과 세부내역서를 중심으로 확인합니다. 검사결과지나 진료 목적 자료가 추가로 필요한지는 가입 회사에 요청 항목을 물어보세요. 청력장애용 진단서를 실손 청구 때문에 먼저 발급받을 필요가 있는지도 확인합니다.')+p('서류를 보완할 때는 “이미 제출한 세부내역의 ABR 항목 외에 무엇을 확인해야 하나요?”라고 질문하세요. 필요한 검사일·결과 자료 범위를 특정하면 다른 날짜 기록을 잘못 내거나 전체 차트를 중복 발급받는 일을 줄일 수 있습니다.'),
h('가상 예시: 청력도만 가지고 있다면')+p('A씨가 ABR 검사비를 청구하면서 예전 순음청력도만 보관하고 있다고 가정합니다. 먼저 이번 검사일 영수증과 세부내역을 맞춥니다. 추가 결과 자료 요청이 있으면 병원에 ABR 결과 확인이 가능한 서류를 문의합니다. 예전 청력도에 검사명을 임의로 바꾸지 않습니다. 실제 지급 사례가 아닌 준비 예시입니다.'),
h('청력검사 실비와 인공와우 수술비 연결')+p(a('/silbi/audiometry-test-vs-hearing-aid','청력검사 실비와 보청기 비용')+'에서 검사비와 구입비를 구분할 수 있습니다. '+a('/surgery-benefit/cochlear-implant-surgery-cost-claim','인공와우 수술비')+'는 실제 수술·장치 비용을 다룹니다. ABR을 받았다는 사실만으로 수술비 담보가 발생하지는 않습니다.')])

add(2,'전정기능검사 실비는 어지럼증 진료에서 실제로 시행한 검사와 비용을 대조합니다. 안진검사·회전검사와 추가 MRI를 구분하고 검사 전 준비·청구자료 확인 순서를 정리합니다.',[
h('전정기능검사 실비, 어지럼증 검사 전체가 한 항목은 아닙니다')+p('전정기능검사 실비를 검색했다면 세부내역서의 실제 검사명을 먼저 확인하세요. “어지럼증 종합검사”라는 설명만으로 안진검사·자세검사·회전검사가 전부 같은 날 시행됐다고 적으면 안 됩니다. 의사가 증상을 평가하며 실제로 선택한 검사와 금액을 대조합니다.'),
h('안진검사·회전검사와 MRI의 역할 비교')+p(a(PLAN[1]['medical'],'서울아산병원 전정기능검사 안내')+'는 눈의 움직임이나 자세·회전 반응 등을 평가하는 여러 검사를 설명합니다. 필요한 경우 CT·MRI 등 추가 평가가 시행될 수 있지만, 전정기능검사와 같은 검사 항목은 아닙니다.')+table(['검사 묶음','확인할 자료','비용 확인 질문'],[['비디오·온도·체위 관련 안진검사','실제 시행명과 날짜','어떤 항목이 포함됐나요?'],['회전·자세 관련 검사','검사실 설명과 시행 내역','예약한 검사와 실제 항목이 같나요?'],['추가 CT·MRI','별도 처방·촬영일·영상 판독','영상검사 비용은 별도인가요?']]),
h('전정기능검사 전 금식·약 복용은 개별 안내를 확인하세요')+p('검사 종류에 따라 준비가 달라집니다. 의료기관의 준비 안내를 읽더라도 복용약을 스스로 일괄 중단하지 말고, 약 이름과 복용 시간을 검사실·처방 의료진에게 알려 조정 계획을 확인하세요. 어지러움이나 메스꺼움이 예상될 때 이동·귀가 방법도 문의합니다.')+p('갑자기 심한 어지러움과 함께 말이 어눌해지거나 팔다리 힘이 빠지는 등 새로운 증상이 있으면 예약검사나 보험 준비를 기다리지 말고 신속하게 진료받으세요. 증상만으로 귀 질환이라고 자가 진단하지 않습니다.'),
h('전정기능검사 비용과 실손 자료 정리')+ul(['검사일별 영수증·세부내역에서 급여·비급여 항목 확인','같은 날 받은 청력검사·영상검사와 항목 분리','가입 실손의 보장범위·공제·한도 확인','진료 목적이나 추가 결과지 요청이 있다면 필요한 범위 문의'])+p('여러 검사를 받았다고 각 항목마다 별도의 일일 한도가 생기는 것은 아닙니다. 한도 적용 단위는 본인 계약에서 확인하세요. 진단서·영상 CD를 모두 먼저 발급받기보다 어떤 사실을 확인하려는 요청인지 물어보는 편이 좋습니다.'),
h('가상 예시: 같은 날 안진검사와 청력검사를 받았다면')+p('B씨가 어지러움으로 진료받고 안진검사와 청력검사를 함께 받았다고 가정합니다. 두 검사를 같은 이름으로 합치지 않고 세부내역의 시행명을 유지합니다. 이후 다른 날 MRI를 받았다면 해당 날짜의 별도 영수증을 연결합니다. 이는 실제 지급 결과를 예측하는 사례가 아닙니다.'),
h('귀 검사 자료와 연결해 읽기')+p(a('/silbi/audiometry-test-vs-hearing-aid','청력검사 실비 안내')+'는 소리를 듣는 기능의 검사비와 보청기 비용을 구분합니다. 어지럼증 평가에서는 청력검사가 함께 있어도 전정검사의 시행 목적·항목을 따로 확인하세요.')])

add(3,'임피던스 청력검사는 고막·중이 상태를 평가하는 검사로 순음청력검사와 역할이 다릅니다. 고막운동성검사 비용과 결과지, 실비 청구 전 확인할 항목을 정리합니다.',[
h('임피던스 청력검사와 순음청력검사는 보는 내용이 다릅니다')+p('임피던스 청력검사 비용을 확인한다면 “청력검사”라는 공통 이름보다 세부 시행명을 먼저 보세요. '+a(PLAN[2]['medical'],'서울대학교병원 청력검사 안내')+'는 외이도 압력을 변화시키며 고막에서 반사되는 에너지를 측정하는 임피던스 검사와 소리 역치를 평가하는 순음검사를 구분합니다. 고막운동성계측 등 실제 시행 항목은 병원 기록을 따릅니다.'),
h('고막운동성검사·순음검사·진찰 자료 비교')+table(['구분','자료에서 찾을 내용','대신할 수 없는 것'],[['임피던스·고막운동성 검사','시행명·검사일·해당 결과 자료','순음청력도와 동일한 점수표가 아님'],['순음청력검사','주파수별 청력도 등','고막·중이 상태 검사 기록을 대체하지 않음'],['고막 진찰·귀 내시경','진찰 소견과 시행 기록','검사 이름이 같다고 임의로 합치지 않기']])+p('검사결과의 유형이나 그래프를 혼자 해석해 중이염·난청을 확정하지 마세요. 같은 검사도 연령·증상·진찰 결과를 함께 고려해 의료진이 판단합니다.'),
h('임피던스 청력검사 비용·실비 확인 순서')+p('증상 진료 중 받은 검사인지, 검진이나 증명서 발급을 위한 검사인지 구분합니다. 실제 계산서의 급여·비급여 표시와 가입 실손의 보장 조건은 별도로 확인하세요. 비급여라는 표시 하나만으로 지급을 보장하거나 전액 제외라고 단정하지 않습니다.')+ul(['세부내역서에서 검사명과 금액 확인','같은 날짜의 순음·어음검사 항목을 분리','최종 본인부담액과 진료일 확인','추가 자료가 필요하면 결과지·진료확인 자료의 범위를 문의']),
h('귀 수술 전 검사와 수술비 청구는 나눠 준비합니다')+p('고막 수술 전에 시행한 검사라도 검사비와 실제 수술비는 다른 항목입니다. 수술확인서의 시행명·수술일과 검사일을 구분하고, 민간 수술비 담보의 지급사유는 그 약관으로 확인합니다. 임피던스 검사만 받았는데 고막 수술을 받은 것으로 청구하면 안 됩니다.'),
h('가상 예시: 영수증에는 두 종류의 청력검사가 있다면')+p('C씨의 세부내역에 순음검사와 고막운동성검사가 함께 적혀 있다고 가정합니다. “청력검사 두 번”이라고 횟수만 적지 않고 각각의 시행명과 비용을 유지합니다. 결과 자료를 요청받으면 어느 검사 자료가 필요한지 먼저 확인합니다. 가상 예시이며 실제 보장 판단이 아닙니다.'),
h('청력검사와 고막성형술 안내')+p(a('/silbi/audiometry-test-vs-hearing-aid','청력검사 비용과 보청기 구입비의 차이')+'와 '+a('/surgery-benefit/tympanoplasty-ear-surgery-claim','고막성형술 청구서류')+'를 이어서 확인할 수 있습니다. 이번 글은 고막·중이 상태 검사 자료에 집중합니다.')])

add(4,'CDR GDS 차이는 치매 평가 결과지를 약관과 비교할 때 중요합니다. CDR·CDR-SB·GDS의 표기와 검사일을 구분하고 점수를 임의 환산하지 않는 확인 방법을 정리합니다.',[
h('CDR GDS 차이, 점수의 이름부터 정확히 읽습니다')+p('CDR GDS 차이를 찾는다면 결과지에 적힌 척도명 전체를 먼저 확인하세요. 둘 다 치매 평가에 쓰이지만 숫자를 서로 그대로 옮기거나, 한쪽 결과로 다른 쪽의 약관 조건을 채웠다고 판단할 수 없습니다. 검사를 통해 나온 평가와 의사의 진단, 민간보험 지급사유를 구분해야 합니다.'),
h('CDR·CDR-SB·GDS 결과지 비교')+p(a(DND,'대한치매학회 2021 개정 진료지침(2022년 발표)')+'의 국문 부록은 CDR과 GDS를 치매 중증도 평가에 사용되는 척도로 설명하며, CDR의 전체 등급과 영역 합산점수(CDR-SB)를 구분합니다. 이 글은 그 구분을 서류 확인에 활용하며 자가 채점표를 제공하지 않습니다.')+table(['결과지 표기','먼저 확인할 점','피해야 할 해석'],[['CDR·global CDR','전체 등급인지와 평가일','다른 검사 숫자를 같은 등급으로 읽기'],['CDR-SB','영역 점수 합산인지','합산점수를 전체 CDR 등급으로 제출하기'],['GDS','전반적퇴화척도인지와 평가일','다른 이름의 GDS 검사와 혼동하거나 임의 환산하기']]),
h('GDS 약어만 보지 말고 검사명 전체를 확인하세요')+p('약어가 같아도 문서에서 뜻하는 검사명이 다를 수 있습니다. 치매 평가에서 말하는 Global Deterioration Scale인지, 다른 평가도구인지 담당 진료팀에게 확인하세요. 결과지의 영문·한글 정식 명칭을 유지하면 보험사나 다른 병원에 전달할 때 혼동을 줄일 수 있습니다.'),
h('치매 진단비 약관과 대조하는 순서')+ul(['보험증권에서 실제 가입한 치매 특약명 찾기','약관의 진단확정·인지기능 장애 정의 확인','요구하는 척도·전문의·진단 자료 범위 확인','결과지의 척도명·평가일·기록 범위 대조','다른 척도 자료만 있다면 대체 인정 조항과 추가 자료 문의'])+p('특정 상품의 예시를 모든 치매보험에 적용하지 않습니다. '+a(POLICY+'#page=328','삼성화재 헤리티지 클래스 2601.3 약관 예시')+'는 CDR을 포함한 치매 상태 정의와 진단 조건을 따로 둡니다. 본인 계약에서는 다른 척도나 조건이 쓰였는지 다시 확인하세요.'),
h('가상 예시: CDR-SB만 적힌 자료를 제출한다면')+p('D씨 가족이 CDR-SB가 적힌 결과지만 가지고 있다고 가정합니다. 이를 임의로 global CDR로 바꾸어 청구하지 않고, 보험사가 확인하려는 척도와 병원에서 발급 가능한 자료를 문의합니다. 보험 요건을 맞추려고 새 검사를 임의로 요구하기보다 기존 기록으로 확인 가능한지 먼저 살핍니다. 실제 지급 사례가 아닙니다.'),
h('진단비 청구와 치료비 실비를 나눠 보기')+p(a('/diagnosis-benefit/dementia-diagnosis-benefit-documents','치매보험 진단비 청구서류')+'는 특약별 진단 자료를, '+a('/silbi/leqembi-silbi-claim','레켐비 실비 청구')+'는 실제 치료비 자료를 다룹니다. 한 평가 결과가 약제 대상·보험금 지급을 모두 자동 결정하는 것은 아닙니다.')],[(DND,'대한치매학회 진료지침·국문 부록','척도 역할과 CDR-SB 구분. 2022년 발표 자료이며 최신 보험 약관 자체가 아님'),(POLICY+'#page=328','삼성화재 치매 특약 약관 예시','2601.3 판본의 CDR 관련 조항. 본인 계약과 별도 대조')])

add(5,'신경심리검사 실비는 정밀 인지평가를 받은 목적과 실제 시행한 검사명을 확인합니다. SNSB 등 검사 비용·결과보고서와 치매 진단서, 평가일·설명일을 나눠 청구자료를 준비합니다.',[
h('신경심리검사 실비와 치매 진단비는 다른 청구입니다')+p('신경심리검사 실비를 준비할 때는 검사를 받은 비용을 청구하는 것인지, 치매 진단비의 진단 자료를 준비하는 것인지 구분하세요. SNSB 같은 검사명과 치매라는 진단명은 같은 의미가 아닙니다. 검사를 받았다는 사실만으로 치매 확진이나 진단비 지급을 단정하지 않습니다.'),
h('정밀 인지검사·척도 평가·진단서 자료 비교')+p(a(PLAN[4]['medical'],'분당서울대학교병원 신경심리검사 안내')+'는 여러 인지기능을 측정·분석하며 상세·추적·간단·맞춤형 검사 등을 구분합니다. 이번에 시행한 검사의 정확한 이름과 구성은 진료팀에 확인하세요. 모든 정밀검사를 통틀어 SNSB라고 바꾸어 적지 않습니다.')+table(['자료','주로 확인하는 내용','분리할 날짜'],[['신경심리검사 보고서','실제 검사도구·평가 내용','검사 시행일'],['CDR 등 척도 결과','약관에서 요구하는 평가 표기','해당 평가일'],['진단서·진료기록','의사의 종합 판단과 진단명','진단일·발급일'],['영수증·세부내역','실제 부담한 검사·진찰 비용','결제·진료일']]),
h('SNSB 검사 비용은 시행 범위와 별도 항목을 대조합니다')+p('예약 때 들은 총액에 진찰·검사·결과 설명·보고서 발급 비용이 포함됐는지 확인합니다. 검사 시간이 길었다는 이유로 비급여 또는 입원에 해당한다고 추정하지 마세요. 실제 영수증과 비용 분류를 기준으로 확인합니다.')+p('무료 선별검사, 진료 중 정밀검사, 단순 건강 확인 목적의 평가는 같은 비용 구조가 아닙니다. 가입 실손의 검사 목적·관련 질환 제외·공제·한도를 대조해야 하므로 “인지검사면 모두 실비”라는 결론을 내리지 않습니다.'),
h('신경심리검사 청구자료 발급 체크리스트')+ul(['의뢰한 진료과와 실제 검사명 확인','평가일·결과 설명일·서류 발급일 구분','영수증과 세부내역을 진료일별로 준비','추가 보고서 요청 시 필요한 항목·범위 확인','이전 검사 자료와 이번 재평가 자료를 분리'])+p('검사 문항이나 정답을 공유하거나 결과를 유리하게 만들기 위한 연습 자료로 쓰지 마세요. 검사 준비, 보청기·안경 사용, 보호자 동행, 복용약은 예약기관의 안내를 따릅니다.'),
h('가상 예시: 검사한 날과 결과를 설명받은 날이 다르다면')+p('E씨가 월요일에 평가를 받고 다음 주 진료에서 결과를 설명받았다고 가정합니다. 검사료와 재진료의 실제 진료일을 나눠 정리하고, 보고서 발급일을 검사일로 바꾸지 않습니다. 필요한 진단 자료는 어떤 날짜의 어떤 기록인지 특정해 문의합니다. 실제 심사 결과를 뜻하는 예시는 아닙니다.'),
h('치매 진단 자료·치료 대상 안내와 연결')+p(a('/diagnosis-benefit/dementia-diagnosis-benefit-documents','치매 진단비 청구서류')+'와 '+a('/guides/alzheimer-injection-therapy','알츠하이머 치료 대상·검사 안내')+'를 함께 읽되, 정밀 인지평가 결과 한 장이 진단비·치료 선택을 모두 대신한다고 보지 않습니다.')])

add(6,'요속검사 잔뇨검사 실비는 배뇨 속도와 배뇨 후 남은 소변을 평가한 비용을 확인합니다. 전립선 초음파와 다른 검사 항목, 검사 전 준비와 영수증·결과 자료의 구분 방법입니다.',[
h('요속검사 잔뇨검사 실비는 검사 항목을 나눠 봅니다')+p('요속검사 잔뇨검사 실비를 알아본다면 전립선 초음파와 같은 검사로 묶지 마세요. '+a(PLAN[5]['medical'],'서울아산병원 안내')+'는 요속검사를 배뇨량과 소변 배출 속도 측정으로, 배뇨 후 잔뇨 확인을 초음파로 남은 양을 살피는 과정으로 설명합니다. 실제 시행명과 진료 목적은 본인의 기록을 확인합니다.'),
h('요속·잔뇨·전립선 초음파 비교')+table(['구분','확인하는 자료','청구 전 구분'],[['요속검사','실제 배뇨 기능 평가 기록','소변 성분 검사와 다른 항목'],['배뇨 후 잔뇨 확인','배뇨 뒤 남은 소변 평가 기록','전립선의 크기·형태 검사와 동일시하지 않기'],['전립선 초음파','해당 부위 영상검사 기록','검사 장비가 같아도 목적·시행명 확인']])+p('결과에 특정 숫자가 있다고 스스로 전립선비대증이나 신경인성 방광을 확정하지 않습니다. 배뇨 증상과 다른 진찰·검사를 의료진이 함께 판단합니다.'),
h('소변을 얼마나 참을지는 검사실에 확인하세요')+p('검사 전 물 섭취량이나 배뇨 준비는 예약기관의 안내를 따르세요. 소변을 이미 봤거나 평소처럼 배뇨하기 어려웠다면 숨기지 말고 검사 담당자에게 알립니다. 일정한 양을 억지로 마시거나 통증을 참아 결과를 맞추려 하지 않습니다.')+p('검사를 다시 받게 됐다면 단순 예약 변경인지 실제 재시행인지, 별도 비용이 발생했는지 확인하세요. 결과가 마음에 들지 않는다는 이유로 기록을 임의 수정하지 않습니다.'),
h('요속검사·잔뇨검사 비용 자료 준비')+ul(['같은 날의 세부내역에서 실제 시행 항목 확인','진찰료·약제비·다른 초음파 비용과 구분','급여·비급여 및 최종 본인부담액 확인','가입 실손의 해당 질환 보장범위와 공제 확인','추가 결과지 요청이 있다면 검사일·필요 내용 문의'])+p('실비 청구를 위해 모든 검사결과지나 진단서를 일괄 발급받기보다 가입 회사가 확인하려는 항목을 먼저 물어보세요. 같은 날 여러 항목을 받았다고 통원 한도가 항목 수만큼 생기는 것은 아닙니다.'),
h('가상 예시: 잔뇨 초음파와 전립선 초음파가 함께 있다면')+p('F씨의 세부내역에 배뇨 후 잔뇨 확인과 전립선 검사가 함께 적혀 있다고 가정합니다. “초음파 두 번”이라는 표현으로 합치지 않고 각각의 시행명·날짜·비용을 정리합니다. 어떤 검사자료를 추가 요청받았는지 특정한 뒤 보완합니다. 실제 지급 사례가 아닙니다.'),
h('전립선 검사비와 PSA 결과 확인')+p(a('/silbi/prostate-ultrasound-cost-claim','전립선 초음파 비용·실비')+'는 형태를 보는 검사 항목을, '+a('/checkups/high-psa-followup','PSA 수치 상승 후 진료 안내')+'는 혈액검사 결과와 진료 확인을 다룹니다. 배뇨 기능 검사만으로 암 진단비를 계산하지 않습니다.')])

add(7,'요역동학검사 실비는 실제 시행한 방광기능검사 구성과 질환·검사 목적을 대조합니다. 단순 요속검사와 다른 범위, 수술 전 자료 및 보험사 보완 요청에서 확인할 항목을 정리합니다.',[
h('요역동학검사 실비, 검사 구성과 진단을 함께 확인합니다')+p('요역동학검사 실비를 준비할 때는 병원이 실제로 시행한 검사 구성을 확인하세요. 배뇨 문제를 평가하는 검사라고 모두 같은 항목이나 보험 조건이 되는 것은 아닙니다. 단순 요속검사 비용만 확인하려는 경우와 여러 기능검사를 받은 경우를 나눠 정리합니다.'),
h('방광기능검사 구성과 수술 자료의 차이')+p(a(PLAN[6]['medical'],'서울아산병원 요역동학검사 안내')+'에는 요속·요도내압·방광내압 등과 상황에 따른 추가 검사들이 설명돼 있습니다. 이 글은 검사 방법을 따라 하는 안내가 아니라 시행 자료를 구분하는 안내입니다.')+table(['상황','병원 자료에서 확인','보험 문의 시 구분'],[['기능검사 평가','실제 시행명·검사일·평가 목적','검사료와 진찰료'],['여러 검사 또는 추가 영상','동일 날짜의 세부 항목과 결과 자료','한 검사의 과정인지 별도 항목인지'],['수술 여부 결정 전 검사','검사 결과와 의사의 치료 계획','검사 시행과 실제 수술 시행은 다름'],['실제 수술 후 청구','수술명·수술일·관련 검사 자료','실손 검사비와 정액 수술비 별도']]),
h('요실금 관련 검사라면 제외 조항도 먼저 확인하세요')+p('요역동학검사는 요실금뿐 아니라 다른 배뇨장애 평가에서도 쓰일 수 있습니다. 본인 진료의 실제 질환과 목적을 확인하고 가입 실손의 보상하지 않는 질병·비용 조항을 살펴보세요. “검사니까 모두 지급” 또는 “이 검사면 모두 요실금 제외”라고 단정하지 않습니다.')+p('청구를 위해 병원에 다른 진단명으로 바꿔 달라고 요청해서는 안 됩니다. 보험사에 실제 진단과 검사 목적을 설명하고 적용 담보·제외 조항의 근거를 문서로 문의하세요.'),
h('수술 전 요역동학검사 자료를 요청받았다면')+ul(['어떤 담보 심사에서 요청한 자료인지 확인','검사명·시행일·판독 내용 중 필요한 범위 문의','이전 검사와 수술 직전 검사가 다르면 날짜별 분리','병원의 검사 결과지와 수술확인서 역할 구분','새로운 검사가 필요한지는 의료진 판단에 따르기'])+p('다른 사람에게 필요했던 자료 목록을 자기 청구에 그대로 적용하지 마세요. 기록 제출을 위한 보완 요청과 추가 진료·검사 필요성 판단은 구분해야 합니다.'),
h('가상 예시: 검사만 받고 수술하지 않았다면')+p('G씨가 배뇨장애로 기능검사를 받았지만 약물치료를 계획했다고 가정합니다. 실제 검사비를 실손 계약과 대조하고, 아직 하지 않은 수술의 정액 수술비를 함께 청구하지 않습니다. 이후 수술을 받으면 그 시점의 시행 기록으로 별도 확인합니다. 가상 예시이며 보장을 확정하지 않습니다.'),
h('전립선 초음파와 다른 질문으로 구분하기')+p(a('/silbi/prostate-ultrasound-cost-claim','전립선 초음파 비용·실비')+'는 해당 부위 영상검사와 비용을 다룹니다. 요역동학검사는 실제 기능검사 구성과 치료 계획에 연결되는 자료를 중심으로 정리하세요.')])

add(8,'전립선 MRI 실비는 암 의심 진료·검진·추적 목적과 실제 촬영 범위를 확인합니다. 일반·조영 MRI 비용 항목, 급여·비급여와 검사자료를 나눠 청구 전 대조하는 방법입니다.',[
h('전립선 MRI 실비는 촬영 목적과 실제 항목을 확인합니다')+p('전립선 MRI 실비를 준비한다면 PSA 결과 뒤 의사가 필요하다고 판단한 촬영인지, 검진 선택 항목인지, 치료 후 추적검사인지 먼저 구분하세요. MRI를 찍었다는 사실만으로 전립선암이 확정되거나 암 진단비가 지급되는 것은 아닙니다.')+p(a(PLAN[7]['medical'],'국가암정보센터 전립선암 진단방법')+'은 전립선 평가에서 여러 검사와 영상의 역할을 설명합니다. 혈액검사·초음파·MRI·조직검사는 서로 같은 자료가 아니므로 의료진이 계획한 검사 목적을 확인해야 합니다.'),
h('일반·조영·판독 비용 비교')+table(['비용 확인 항목','병원에 물을 내용','견적 비교 시 주의'],[['촬영 범위·방법','전립선 촬영의 실제 시행 항목','다른 골반 부위 촬영과 혼동하지 않기'],['조영제 사용','조영 여부와 관련 비용 포함 범위','조영제·추가 비용을 총액과 구분'],['판독·외부영상','촬영료와 판독료 포함 여부','기존 영상 재판독과 새 촬영 구분'],['진정·관찰','실제로 계획·시행했는지','불안하다고 진정 비용이 자동 발생하지 않음']]),
h('병원 공개가격은 내 진료 총액과 다릅니다')+p(a(PRICE,'보라매병원 비급여 공개 항목')+'에는 전립선 일반 MRI가 620,000원으로 표시된 항목이 있으며 촬영·판독을 포함한 1회 비용이라는 설명이 있습니다. 해당 항목의 변경일은 2026년 6월 1일입니다. 이는 급여 인정기준 외 비급여의 병원별 예시이며 전국 평균이나 조영 MRI의 총액이 아닙니다.')+p('검진 패키지 가격과 진료 중 급여 적용 비용도 같은 기준으로 비교하면 안 됩니다. 병원에 본인의 급여 적용 여부·촬영 범위·포함 항목을 확인하고, 실손은 가입 약관에서 별도로 대조하세요.'),
h('전립선 MRI 실비 청구서류 체크리스트')+ul(['진료비 영수증·세부내역서의 촬영일·검사명 확인','조영제·진정·다른 검사 항목이 있으면 구분','가입 계약의 급여·비급여 MRI 담보와 한도 확인','추가 요청 시 처방 사유·판독 자료의 필요한 범위 문의','다른 병원 촬영이면 해당 병원의 비용자료 별도 준비'])+p('다른 병원에 진료 자료를 전달하기 위한 영상 CD와 보험금 청구에 필요한 자료는 같지 않을 수 있습니다. 보험사가 영상 자체를 요구하는지 확인하기 전에 CD부터 발급받을 필요는 없습니다.'),
h('가상 예시: 초음파 뒤 다른 병원에서 MRI를 받았다면')+p('H씨가 첫 병원에서 초음파를 받고 두 번째 병원에서 MRI를 촬영했다고 가정합니다. 기관별 영수증을 촬영일에 맞춰 준비하고 이전 검사·의뢰 사유의 연결이 필요한지 문의합니다. 두 병원 비용을 한 기관 영수증처럼 합쳐 쓰지 않습니다. 실제 심사나 진단 결과를 뜻하는 예시는 아닙니다.'),
h('초음파·일반 MRI 청구와 연결해 읽기')+p(a('/silbi/prostate-ultrasound-cost-claim','전립선 초음파 비용·실비')+'와 '+a('/silbi/mri-silbi-claim','MRI 실비 청구 공통 안내')+'를 함께 확인할 수 있습니다. 이번 글은 전립선 촬영 범위와 조영·판독 비용을 중심으로 구분합니다.')],[(PRICE,'보라매병원 전립선 관련 비급여 항목 검색','전립선 일반 MRI 공개가격의 병원별 예시. 총 진료비 아님')])

add(9,'특수건강검진 일반건강검진 차이는 대상 업무와 검진 목적에 있습니다. 유해인자 노출에 따른 검진, 배치전검진과 정기 일반검진을 구분해 회사·검진기관에 확인할 자료를 정리합니다.',[
h('특수건강검진 일반건강검진 차이는 대상과 목적입니다')+p('특수건강검진 일반건강검진 차이를 확인할 때는 회사가 안내한 정확한 검진 종류와 본인의 업무를 먼저 확인하세요. 국가 일반검진을 받았다는 사실만으로 필요한 특수건강진단까지 끝났다고 판단하면 안 됩니다. 반대로 모든 직장인이 모든 특수검사를 받아야 하는 것도 아닙니다.'),
h('일반·특수·배치전 건강진단 비교')+p(a(PLAN[8]['medical'],'산업안전보건법 제129~132조')+'는 일반건강진단, 해당 유해인자·업무에 따른 특수건강진단, 배치 예정 업무 적합성 평가를 위한 배치전건강진단 등을 구분합니다. 건강검진이라는 일상 표현보다 사업장이 지정한 법정 종류를 확인하는 것이 중요합니다.')+table(['구분','대상·목적 확인','회사에 물을 내용'],[['일반건강진단','근로자의 일반 건강관리','올해 대상 여부·인정 가능한 검진'],['특수건강진단','해당 유해인자 노출 업무 등','업무·유해인자에 맞는 대상·기관·주기'],['배치전건강진단','대상 업무 배치 전 적합성 평가','예정 업무와 배치 전 검사 일정']]),
h('특수건강검진을 매년 한 번으로 일괄 계산하지 마세요')+p('검진 시기·주기·항목은 해당 유해인자와 법령상 기준에 따라 달라집니다. 일반검진 주기를 특수검진에 그대로 옮기거나, 작년에 받았으니 올해 모든 검진이 면제된다고 판단하지 않습니다. 새 부서로 이동했다면 업무 변화에 따른 검진 필요 여부도 확인하세요.'),
h('검진 예약 전 준비할 업무·기록 체크리스트')+ul(['회사 안내문에서 검진 종류와 대상 업무 확인','담당자가 안내한 유해인자·검진기관·일정 확인','다른 기관 검진을 받았다면 인정 여부와 증빙 문의','검진 뒤 결과 반영·추가 진료·사후관리 안내 확인','개인 결과 자료를 제출할 공식 경로 확인'])+p('의료진과 사업장 담당자에게 필요한 정보를 사실대로 전달하세요. 이 글은 개인의 업무 적합 여부나 채용·배치 결정을 대신 판정하지 않습니다.'),
h('개인 검진 결과는 공개 자료로 취급하지 않습니다')+p('법은 건강진단 결과의 설명과 사용 목적, 개인 결과의 공개에 관한 의무를 둡니다. 제출이 필요하다면 담당 부서·목적·범위를 먼저 확인하고 회사 전체 채팅방 같은 공개 경로에 검사결과를 올리지 마세요. 의무 이행에 필요한 제출 절차와 불필요한 공개를 구분합니다.'),
h('가상 예시: 국가검진을 받고 업무가 바뀌었다면')+p('I씨가 국가검진을 받은 뒤 다른 업무로 이동할 예정이라고 가정합니다. 일반검진 수검 사실과 새 업무에 필요한 배치전·특수건강진단 여부를 회사 담당자에게 각각 확인합니다. 기존 결과지 한 장으로 모든 절차를 대신한다고 보지 않습니다. 가상 절차 예시이며 개인 업무 적합 판정이 아닙니다.')+p(a('/checkups/workplace-health-checkup-missed-penalty','직장인 미수검 과태료 확인')+'와 '+a('/checkups/health-checkup-target-2026','일반건강검진 대상자 확인')+'은 각각 의무·대상 조회의 다른 질문을 다룹니다.')])

add(10,'채용 건강검진 대체 통보서는 기존 국가건강검진 결과를 활용하는 제출용 서류입니다. 발급 경로, 최근 검진 기록의 반영과 제출처 인정 여부, 별도 검사가 필요한 경우의 확인 순서를 정리합니다.',[
h('채용 건강검진 대체 통보서 발급 전 제출처부터 확인합니다')+p('채용 건강검진 대체 통보서 발급을 준비한다면 채용기관이 그 서류를 인정하는지 먼저 확인하세요. 기존 국가건강검진 결과를 이용하는 서류여서 발급만으로 모든 채용검사·별도 확인서가 대체되는 것은 아닙니다. 이 글은 서류 발급·제출 준비 안내이며 개인의 채용 적격 여부를 판정하지 않습니다.'),
h('대체 통보서·일반 결과지·채용검사서 비교')+p(a(PLAN[9]['medical'],'국민건강보험공단 공식 발급 메뉴')+'는 채용 제출용 통보서를 조회하는 서비스입니다. 공단 홈페이지의 건강모아·나의 건강 메뉴에서도 해당 항목을 찾을 수 있습니다. 본인이 지원한 공고의 서류명·기준일·추가 항목과 대체 통보서 인정 여부를 우선 확인하세요.')+table(['자료','확인할 내용','제출 전 문의'],[['채용 건강검진 대체 통보서','기존 국가검진 결과 활용','해당 기관이 인정하는지'],['일반건강검진 결과통보서','일반 검진 결과 안내','그대로 제출 가능한지·필요 범위'],['별도 채용 신체검사서','요구 양식·검사항목','지정 기관·발급일·유효 기준']]),
h('공단 홈페이지에서 조회·발급하는 순서')+ul(['국민건강보험공단 공식 홈페이지에서 본인 인증','사이트 검색에서 채용 건강검진 대체 통보서 찾기','반영된 검진연도·검진일과 본인 정보 확인','요구되는 제출처 정보를 정확히 입력','인쇄·저장 가능 방법과 제출처의 접수 방식 확인'])+p('공식 발급 메뉴를 이용하고 검색광고의 대행 사이트에 인증정보를 주지 마세요. 이 글은 개인 계정으로 로그인하거나 서류를 대신 발급한 기록이 아닙니다. 메뉴 이름·위치는 홈페이지 개편에 따라 달라질 수 있어 공식 사이트 검색을 함께 이용합니다.'),
h('최근 검진 기록이 조회되지 않는다면')+p(a('https://www.suwon.go.kr/common-upload/upload/board/2026/6/1/f4736e67-343d-4027-9362-053a94173e95.pdf#page=7','2026년 공공기관 채용공고의 안내 예시')+'는 최근 2년 내 국가건강검진 결과를 활용하며 검진기관에서 자료가 제출된 이후에 제공되는 점을 설명합니다. 공고의 예시는 모든 제출처의 공통 인정 기준은 아니며, 실제 조회 가능한 기록은 공단 서비스에서 확인하세요. 검진 직후에는 자료 반영 전일 수 있습니다.')+p('결과가 안 보인다면 실제 검진일·결과 반영 상태와 대상 기록 여부를 공단·검진기관에 확인합니다. 제출 마감이 가까우면 채용기관에 다른 서류나 보완 제출이 가능한지 문의하세요. 발급일이 최근이어도 검진일이 바뀌지는 않습니다.'),
h('가상 예시: 결과지는 있지만 대체 통보서는 안 보인다면')+p('J씨가 검진기관의 결과지를 받았지만 공단 발급 메뉴에 아직 기록이 없다고 가정합니다. 검진기관에 자료 반영 상태를 확인하고, 제출처에 요구하는 서류와 마감을 설명해 안내를 받습니다. 임의로 일반 결과지의 제목을 대체 통보서로 바꾸지 않습니다. 실제 접수 허용을 보장하는 사례가 아닙니다.'),
h('결과 재발급·면허용 기록과 구분하기')+p(a('/checkups/health-checkup-result-reissue','건강검진 결과 재발급')+'는 원래 결과 자료의 조회를, '+a('/checkups/driving-license-renewal-health-checkup','면허 갱신 건강검진 자료 이용')+'는 다른 제출 목적을 다룹니다. 용도가 다른 서류를 서로 자동 대체된다고 보지 말고 제출처 기준을 확인하세요.')],[("https://www.suwon.go.kr/common-upload/upload/board/2026/6/1/f4736e67-343d-4027-9362-053a94173e95.pdf#page=7",'공공기관 채용공고의 제출서류 안내 예시','2026년 공고 7쪽의 검진 기록 안내. 해당 기관의 과거 공고이며 일반 발급 양식이 아님')])
